            </div>
            <div className="stat-card">
              <div className="stat-icon green"><CheckCircle size={22} /></div>
              <div className="stat-info">
                <div className="stat-value">{lowRiskCount}</div>
                <div className="stat-label">Low Risk/Stable</div>
