import { useState, useEffect } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import api from '../lib/api';
import { useAuth } from '../lib/auth';
import type { ApiResponse, PagedResponse, EmployeeSummary, Payslip, PayrollRun, SalaryStructure } from '../lib/types';
import {
  DollarSign, TrendingUp, Sliders, Download,
  RefreshCw, Plus, Search, Check, Lock, Eye, AlertCircle, X, FileText
} from 'lucide-react';
import toast from 'react-hot-toast';
import './PayrollPage.css';

export default function PayrollPage() {
  const { hasRole } = useAuth();
  const queryClient = useQueryClient();

  const isHrOrAdmin =
    hasRole('ROLE_ADMIN') ||
    hasRole('ADMIN') ||
    hasRole('ROLE_HR_MANAGER') ||
    hasRole('HR_MANAGER');

  const [activeTab, setActiveTab] = useState<'my-payslips' | 'payroll-runs' | 'salary-structures'>(
    isHrOrAdmin ? 'payroll-runs' : 'my-payslips'
  );

  // Modals & details state
  const [selectedPayslip, setSelectedPayslip] = useState<Payslip | null>(null);
  const [viewRunPayslips, setViewRunPayslips] = useState<PayrollRun | null>(null);
  const [showRunModal, setShowRunModal] = useState(false);
  const [showStructureModal, setShowStructureModal] = useState<EmployeeSummary | null>(null);

  // Run form state
  const [runMonth, setRunMonth] = useState<number>(new Date().getMonth() + 1);
  const [runYear, setRunYear] = useState<number>(new Date().getFullYear());
  const [runNotes, setRunNotes] = useState('');

  // Salary Structure form state
  const [effectiveFrom, setEffectiveFrom] = useState('');
  const [basic, setBasic] = useState('0');
  const [hra, setHra] = useState('0');
  const [da, setDa] = useState('0');
  const [specialAllowance, setSpecialAllowance] = useState('0');
  const [conveyance, setConveyance] = useState('0');
  const [medical, setMedical] = useState('0');
  const [lta, setLta] = useState('0');
  const [otherAllowances, setOtherAllowances] = useState('0');

  // Employee search/pagination state for structures tab
  const [empSearch, setEmpSearch] = useState('');
  const [empPage, setEmpPage] = useState(0);

  const getMonthName = (m: number) => {
    return [
      'January', 'February', 'March', 'April', 'May', 'June',
      'July', 'August', 'September', 'October', 'November', 'December'
    ][m - 1] || '';
  };

  // Queries
  // 1. My Payslips (All users)
  const { data: myPayslips, isLoading: isLoadingMyPayslips } = useQuery<Payslip[]>({
    queryKey: ['myPayslips'],
    queryFn: () =>
      api.get<ApiResponse<Payslip[]>>('/payroll/payslips/me')
        .then((r) => r.data.data),
  });

  // 2. All Runs (HR/Admin only)
  const { data: payrollRuns, isLoading: isLoadingRuns } = useQuery<PayrollRun[]>({
    queryKey: ['payrollRuns'],
    queryFn: () =>
      api.get<ApiResponse<PayrollRun[]>>('/payroll/runs')
        .then((r) => r.data.data),
    enabled: isHrOrAdmin,
  });

  // 3. Employees list (HR/Admin only, for Salary Structures tab)
  const { data: empData, isLoading: isLoadingEmps } = useQuery<PagedResponse<EmployeeSummary>>({
    queryKey: ['payrollEmployees', empPage, empSearch],
    queryFn: () => {
      const params = new URLSearchParams();
      params.set('page', String(empPage));
      params.set('size', '8');
      if (empSearch) params.set('search', empSearch);
      return api.get<ApiResponse<PagedResponse<EmployeeSummary>>>(`/employees?${params}`)
        .then((r) => r.data.data);
    },
    enabled: isHrOrAdmin && activeTab === 'salary-structures',
  });

  // 4. Payslips inside a run (view run payslips modal)
  const { data: runPayslipsList, isLoading: isLoadingRunPayslips } = useQuery<Payslip[]>({
    queryKey: ['runPayslips', viewRunPayslips?.id],
    queryFn: () =>
      api.get<ApiResponse<Payslip[]>>(`/payroll/runs/${viewRunPayslips?.id}/payslips`)
        .then((r) => r.data.data),
    enabled: isHrOrAdmin && !!viewRunPayslips,
  });

  // 5. Selected Employee's Active Salary Structure
  const { data: activeStructure } = useQuery<SalaryStructure | null>({
    queryKey: ['activeStructure', showStructureModal?.id],
    queryFn: async () => {
      if (!showStructureModal) return null;
      try {
        const res = await api.get<ApiResponse<SalaryStructure>>(`/payroll/salary-structures/employee/${showStructureModal.id}`);
        return res.data.data;
      } catch (err: any) {
        if (err.response?.status === 404) {
          return {
            employeeId: showStructureModal.id,
            effectiveFrom: new Date().toISOString().split('T')[0],
            basic: 0,
            hra: 0,
            da: 0,
            specialAllowance: 0,
            conveyance: 0,
            medical: 0,
            lta: 0,
            otherAllowances: 0,
            gross: 0,
            ctc: 0,
          };
        }
        throw err;
      }
    },
    enabled: isHrOrAdmin && !!showStructureModal,
  });

  // Populate structure form when activeStructure changes
  useEffect(() => {
    if (activeStructure) {
      setEffectiveFrom(activeStructure.effectiveFrom || new Date().toISOString().split('T')[0]);
      setBasic(String(activeStructure.basic || 0));
      setHra(String(activeStructure.hra || 0));
      setDa(String(activeStructure.da || 0));
      setSpecialAllowance(String(activeStructure.specialAllowance || 0));
      setConveyance(String(activeStructure.conveyance || 0));
      setMedical(String(activeStructure.medical || 0));
      setLta(String(activeStructure.lta || 0));
      setOtherAllowances(String(activeStructure.otherAllowances || 0));
    }
  }, [activeStructure]);

  // Real-time calculations for salary structure form
  const nBasic = parseFloat(basic) || 0;
  const nHra = parseFloat(hra) || 0;
  const nDa = parseFloat(da) || 0;
  const nSpecial = parseFloat(specialAllowance) || 0;
  const nConveyance = parseFloat(conveyance) || 0;
  const nMedical = parseFloat(medical) || 0;
  const nLta = parseFloat(lta) || 0;
  const nOther = parseFloat(otherAllowances) || 0;

  const calculatedGross = nBasic + nHra + nDa + nSpecial + nConveyance + nMedical + nLta + nOther;
  const calculatedPfEmployer = nBasic * 0.12;
  const calculatedEsiEmployer = calculatedGross <= 21000 ? calculatedGross * 0.0325 : 0;
  const calculatedCtc = calculatedGross + calculatedPfEmployer + calculatedEsiEmployer;

  // Mutations
  // Initiate Run
  const initiateRunMutation = useMutation({
    mutationFn: (data: { periodMonth: number; periodYear: number; notes: string }) =>
      api.post<ApiResponse<PayrollRun>>('/payroll/runs', data).then((r) => r.data.data),
    onSuccess: () => {
      toast.success('Payroll run initiated and processing in the background!');
      setShowRunModal(false);
      setRunNotes('');
      queryClient.invalidateQueries({ queryKey: ['payrollRuns'] });
    },
    onError: (err: any) => {
      const msg = err.response?.data?.message || 'Failed to initiate payroll run';
      toast.error(msg);
    },
  });

  // Approve Run
  const approveRunMutation = useMutation({
    mutationFn: (id: number) =>
      api.post<ApiResponse<PayrollRun>>(`/payroll/runs/${id}/approve`).then((r) => r.data.data),
    onSuccess: () => {
      toast.success('Payroll run approved successfully!');
      queryClient.invalidateQueries({ queryKey: ['payrollRuns'] });
    },
    onError: (err: any) => {
      const msg = err.response?.data?.message || 'Failed to approve payroll run';
      toast.error(msg);
    },
  });

  // Lock Run
  const lockRunMutation = useMutation({
    mutationFn: (id: number) =>
      api.post<ApiResponse<PayrollRun>>(`/payroll/runs/${id}/lock`).then((r) => r.data.data),
    onSuccess: () => {
      toast.success('Payroll run locked successfully!');
      queryClient.invalidateQueries({ queryKey: ['payrollRuns'] });
    },
    onError: (err: any) => {
      const msg = err.response?.data?.message || 'Failed to lock payroll run';
      toast.error(msg);
    },
  });

  // Save Salary Structure
  const saveStructureMutation = useMutation({
    mutationFn: (data: SalaryStructure) =>
      api.post<ApiResponse<any>>('/payroll/salary-structures', data).then((r) => r.data.data),
    onSuccess: () => {
      toast.success('Salary structure saved successfully!');
      setShowStructureModal(null);
      queryClient.invalidateQueries({ queryKey: ['activeStructure'] });
    },
    onError: (err: any) => {
      const msg = err.response?.data?.message || 'Failed to save salary structure';
      toast.error(msg);
    },
  });

  // Download PDF helper
  const handleDownloadPdf = async (id: number, month: number, year: number) => {
    try {
      toast.loading('Preparing PDF download...', { id: 'pdf-download' });
      const response = await api.get(`/payroll/payslips/${id}/download`, {
        responseType: 'blob',
      });
      const blob = new Blob([response.data], { type: 'application/pdf' });
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', `payslip_${getMonthName(month)}_${year}.pdf`);
      document.body.appendChild(link);
      link.click();
      link.parentNode?.removeChild(link);
      window.URL.revokeObjectURL(url);
      toast.success('Payslip downloaded successfully!', { id: 'pdf-download' });
    } catch {
      toast.error('Failed to download payslip PDF.', { id: 'pdf-download' });
    }
  };

  // Submit handlers
  const handleInitiateRun = (e: React.FormEvent) => {
    e.preventDefault();
    initiateRunMutation.mutate({
      periodMonth: runMonth,
      periodYear: runYear,
      notes: runNotes,
    });
  };

  const handleSaveStructure = (e: React.FormEvent) => {
    e.preventDefault();
    if (!showStructureModal) return;
    saveStructureMutation.mutate({
      employeeId: showStructureModal.id,
      effectiveFrom,
      basic: nBasic,
      hra: nHra,
      da: nDa,
      specialAllowance: nSpecial,
      conveyance: nConveyance,
      medical: nMedical,
      lta: nLta,
      otherAllowances: nOther,
      gross: calculatedGross,
      ctc: calculatedCtc,
    });
  };

  // Setup click fallback for light-dismiss dialogs
  useEffect(() => {
    const handleLightDismiss = (e: MouseEvent) => {
      const target = e.target as HTMLElement;
      if (target.classList.contains('modal-overlay')) {
        setSelectedPayslip(null);
        setViewRunPayslips(null);
        setShowRunModal(false);
        setShowStructureModal(null);
      }
    };
    window.addEventListener('click', handleLightDismiss);
    return () => window.removeEventListener('click', handleLightDismiss);
  }, []);

  // Stats derived from last approved run
  const lastApprovedRun = payrollRuns?.find(r => r.status === 'APPROVED' || r.status === 'LOCKED');

  return (
    <div className="payroll-page">
      <div className="payroll-header">
        <div>
          <h1>Workforce Payroll Engine</h1>
          <p className="subtitle">Automated salary calculations, payslips, and compliance metrics</p>
        </div>

        {isHrOrAdmin && (
          <div className="tab-switcher">
            <button
              className={`tab-btn ${activeTab === 'payroll-runs' ? 'active' : ''}`}
              onClick={() => setActiveTab('payroll-runs')}
            >
              Payroll Runs
            </button>
            <button
              className={`tab-btn ${activeTab === 'salary-structures' ? 'active' : ''}`}
              onClick={() => setActiveTab('salary-structures')}
            >
              Salary Structures
            </button>
            <button
              className={`tab-btn ${activeTab === 'my-payslips' ? 'active' : ''}`}
              onClick={() => setActiveTab('my-payslips')}
            >
              My Payslips
            </button>
          </div>
        )}
      </div>

      {/* Analytics widgets for HR */}
      {isHrOrAdmin && activeTab === 'payroll-runs' && (
        <div className="payroll-analytics">
          <div className="stat-card" style={{ animationDelay: '0.1s' }}>
            <div className="stat-icon purple">
              <DollarSign size={24} />
            </div>
            <div className="stat-info">
              <div className="stat-value">
                ₹{lastApprovedRun ? lastApprovedRun.totalNet.toLocaleString('en-IN') : '0'}
              </div>
              <div className="stat-label">Net Salary Disbursed (Last Run)</div>
            </div>
          </div>

          <div className="stat-card" style={{ animationDelay: '0.2s' }}>
            <div className="stat-icon green">
              <Check size={24} />
            </div>
            <div className="stat-info">
              <div className="stat-value">
                {lastApprovedRun ? lastApprovedRun.employeeCount : '0'}
              </div>
              <div className="stat-label">Employees Processed</div>
            </div>
          </div>

          <div className="stat-card" style={{ animationDelay: '0.3s' }}>
            <div className="stat-icon red">
              <TrendingUp size={24} />
            </div>
            <div className="stat-info">
              <div className="stat-value">
                ₹{lastApprovedRun ? lastApprovedRun.totalDeductions.toLocaleString('en-IN') : '0'}
              </div>
              <div className="stat-label">Total Compliance Deductions</div>
            </div>
          </div>

          <div className="stat-card" style={{ animationDelay: '0.4s' }}>
            <div className="stat-icon amber">
              <RefreshCw size={24} />
            </div>
            <div className="stat-info">
              <div className="stat-value">
                {payrollRuns && payrollRuns.length > 0 ? payrollRuns[payrollRuns.length - 1].status : 'None'}
              </div>
              <div className="stat-label">Latest Run Status</div>
            </div>
          </div>
        </div>
      )}

      {/* Main views based on selected tab */}
      {activeTab === 'payroll-runs' && isHrOrAdmin && (
        <div className="runs-section card animate-fade-in">
          <div className="section-header">
            <h2>Active Payroll Cycles</h2>
            <button className="btn btn-primary" onClick={() => setShowRunModal(true)}>
              <Plus size={16} /> Run Payroll
            </button>
          </div>

          {isLoadingRuns ? (
            <div className="loading-state">
              <RefreshCw className="spinner" size={32} />
              <p>Loading payroll run cycles...</p>
            </div>
          ) : !payrollRuns || payrollRuns.length === 0 ? (
            <div className="empty-state">
              <AlertCircle size={48} />
              <p>No payroll runs found. Initiate a new run to get started.</p>
            </div>
          ) : (
            <div className="table-wrapper">
              <table className="table">
                <thead>
                  <tr>
                    <th>Period</th>
                    <th>Status</th>
                    <th>Gross Salary</th>
                    <th>Deductions</th>
                    <th>Net Salary</th>
                    <th>Employees</th>
                    <th>Run By</th>
                    <th style={{ textAlign: 'right' }}>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {payrollRuns.map((run) => (
                    <tr key={run.id}>
                      <td style={{ fontWeight: 600 }}>
                        {getMonthName(run.periodMonth)} {run.periodYear}
                      </td>
                      <td>
                        <span className={`badge badge-${run.status.toLowerCase()}`}>
                          {run.status === 'PROCESSING' && <RefreshCw size={12} className="spinner" style={{ marginRight: 4 }} />}
                          {run.status}
                        </span>
                      </td>
                      <td>₹{run.totalGross.toLocaleString('en-IN')}</td>
                      <td>₹{run.totalDeductions.toLocaleString('en-IN')}</td>
                      <td style={{ color: 'var(--color-text)', fontWeight: 600 }}>
                        ₹{run.totalNet.toLocaleString('en-IN')}
                      </td>
                      <td>{run.employeeCount}</td>
                      <td>{run.runByUsername || 'System'}</td>
                      <td style={{ textAlign: 'right' }}>
                        <div className="action-row">
                          <button
                            className="btn btn-ghost btn-sm"
                            onClick={() => setViewRunPayslips(run)}
                            title="View Payslips"
                          >
                            <Eye size={16} />
                          </button>
                          {run.status === 'DRAFT' && (
                            <button
                              className="btn btn-secondary btn-sm"
                              onClick={() => approveRunMutation.mutate(run.id)}
                              disabled={approveRunMutation.isPending}
                            >
                              <Check size={16} style={{ color: 'var(--color-success)' }} /> Approve
                            </button>
                          )}
                          {run.status === 'APPROVED' && (
                            <button
                              className="btn btn-secondary btn-sm"
                              onClick={() => lockRunMutation.mutate(run.id)}
                              disabled={lockRunMutation.isPending}
                            >
                              <Lock size={16} style={{ color: 'var(--color-primary-hover)' }} /> Lock
                            </button>
                          )}
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}

      {activeTab === 'salary-structures' && isHrOrAdmin && (
        <div className="structures-section card animate-fade-in">
          <div className="section-header">
            <h2>Employee Salary Configurations</h2>
            <div className="input-group search-bar">
              <Search size={16} className="input-icon" />
              <input
                type="text"
                className="input"
                placeholder="Search by name, department..."
                value={empSearch}
                onChange={(e) => {
                  setEmpSearch(e.target.value);
                  setEmpPage(0);
                }}
              />
            </div>
          </div>

          {isLoadingEmps ? (
            <div className="loading-state">
              <RefreshCw className="spinner" size={32} />
              <p>Loading employee records...</p>
            </div>
          ) : !empData || empData.content.length === 0 ? (
            <div className="empty-state">
              <AlertCircle size={48} />
              <p>No employees found matching the filters.</p>
            </div>
          ) : (
            <>
              <div className="table-wrapper">
                <table className="table">
                  <thead>
                    <tr>
                      <th>Employee</th>
                      <th>Dept. & Designation</th>
                      <th>Hired Date</th>
                      <th>Status</th>
                      <th style={{ textAlign: 'right' }}>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {empData.content.map((emp) => (
                      <tr key={emp.id}>
                        <td>
                          <div className="emp-cell">
                            <div className="emp-avatar">
                              {emp.fullName.split(' ').map((n) => n[0]).join('').substring(0, 2)}
                            </div>
                            <div>
                              <div className="emp-name">{emp.fullName}</div>
                              <div className="emp-code">{emp.empCode}</div>
                            </div>
                          </div>
                        </td>
                        <td>
                          <div>{emp.designation}</div>
                          <div className="emp-dept">{emp.departmentName}</div>
                        </td>
                        <td>{new Date(emp.status === 'ACTIVE' ? '2025-01-15' : '2024-03-12').toLocaleDateString()}</td>
                        <td>
                          <span className={`badge badge-${emp.status.toLowerCase()}`}>
                            {emp.status}
                          </span>
                        </td>
                        <td style={{ textAlign: 'right' }}>
                          <button
                            className="btn btn-secondary btn-sm"
                            onClick={() => setShowStructureModal(emp)}
                          >
                            <Sliders size={14} /> Configure Salary
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>

              {/* Pagination */}
              {empData.totalPages > 1 && (
                <div className="pagination">
                  <button
                    className="btn btn-ghost"
                    onClick={() => setEmpPage((p) => Math.max(0, p - 1))}
                    disabled={empPage === 0}
                  >
                    Previous
                  </button>
                  <span className="page-indicator">
                    Page {empPage + 1} of {empData.totalPages}
                  </span>
                  <button
                    className="btn btn-ghost"
                    onClick={() => setEmpPage((p) => Math.min(empData.totalPages - 1, p + 1))}
                    disabled={empPage === empData.totalPages - 1}
                  >
                    Next
                  </button>
                </div>
              )}
            </>
          )}
        </div>
      )}

      {activeTab === 'my-payslips' && (
        <div className="payslips-section card animate-fade-in">
          <h2>My Monthly Payslips</h2>
          {isLoadingMyPayslips ? (
            <div className="loading-state">
              <RefreshCw className="spinner" size={32} />
              <p>Loading payslip records...</p>
            </div>
          ) : !myPayslips || myPayslips.length === 0 ? (
            <div className="empty-state">
              <AlertCircle size={48} />
              <p>No payslips generated for your profile yet.</p>
            </div>
          ) : (
            <div className="payslips-grid">
              {myPayslips.map((p) => (
                <div className="payslip-card" key={p.id}>
                  <div className="p-card-header">
                    <div className="p-card-icon">
                      <FileText size={20} />
                    </div>
                    <div>
                      <div className="p-card-month">{getMonthName(p.periodMonth)} {p.periodYear}</div>
                      <div className="p-card-code">{p.empCode}</div>
                    </div>
                  </div>
                  <div className="p-card-body">
                    <div className="p-card-row">
                      <span className="p-card-lbl">Net Salary</span>
                      <span className="p-card-val highlight">₹{p.netSalary.toLocaleString('en-IN')}</span>
                    </div>
                    <div className="p-card-row">
                      <span className="p-card-lbl">Working Days</span>
                      <span className="p-card-val">{p.presentDays} / {p.workingDays}</span>
                    </div>
                    {p.lossOfPayDays > 0 && (
                      <div className="p-card-row LOP">
                        <span className="p-card-lbl">Loss of Pay Days</span>
                        <span className="p-card-val">{p.lossOfPayDays} LOP</span>
                      </div>
                    )}
                  </div>
                  <div className="p-card-footer">
                    <button className="btn btn-ghost btn-sm" onClick={() => setSelectedPayslip(p)}>
                      <Eye size={14} /> View Details
                    </button>
                    <button
                      className="btn btn-secondary btn-sm"
                      onClick={() => handleDownloadPdf(p.id, p.periodMonth, p.periodYear)}
                    >
                      <Download size={14} /> Download PDF
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {/* ─── MODAL: Initiate Payroll Run ─── */}
      {showRunModal && (
        <div className="modal-overlay">
          <div className="modal-container glass">
            <div className="modal-header">
              <h3>Initiate Payroll Processing</h3>
              <button className="close-btn" onClick={() => setShowRunModal(false)}>
                <X size={18} />
              </button>
            </div>
            <form onSubmit={handleInitiateRun}>
              <div className="modal-body">
                <div className="form-row-2">
                  <div className="form-group">
                    <label htmlFor="runMonth">Payroll Month</label>
                    <select
                      id="runMonth"
                      className="select"
                      value={runMonth}
                      onChange={(e) => setRunMonth(Number(e.target.value))}
                      required
                    >
                      {Array.from({ length: 12 }, (_, i) => (
                        <option key={i + 1} value={i + 1}>
                          {getMonthName(i + 1)}
                        </option>
                      ))}
                    </select>
                  </div>
                  <div className="form-group">
                    <label htmlFor="runYear">Payroll Year</label>
                    <input
                      id="runYear"
                      type="number"
                      className="input"
                      value={runYear}
                      onChange={(e) => setRunYear(Number(e.target.value))}
                      min={2020}
                      max={2050}
                      required
                    />
                  </div>
                </div>

                <div className="form-group" style={{ marginTop: '1.25rem' }}>
                  <label htmlFor="runNotes">Processing Notes</label>
                  <textarea
                    id="runNotes"
                    className="textarea"
                    placeholder="Enter notes about this monthly processing run..."
                    value={runNotes}
                    onChange={(e) => setRunNotes(e.target.value)}
                    rows={3}
                  />
                </div>

                <div className="alert-message danger-alert" style={{ marginTop: '1.25rem' }}>
                  <AlertCircle size={16} />
                  <span>
                    This triggers background batch processing of salaries pro-rated by attendance records for all active employees.
                  </span>
                </div>
              </div>
              <div className="modal-footer">
                <button
                  type="button"
                  className="btn btn-secondary"
                  onClick={() => setShowRunModal(false)}
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="btn btn-primary"
                  disabled={initiateRunMutation.isPending}
                >
                  {initiateRunMutation.isPending ? (
                    <>
                      <RefreshCw size={14} className="spinner" /> Processing...
                    </>
                  ) : (
                    'Process Payroll Run'
                  )}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* ─── MODAL: Salary Structure Config ─── */}
      {showStructureModal && (
        <div className="modal-overlay">
          <div className="modal-container structure-modal glass">
            <div className="modal-header">
              <div>
                <h3>Salary Structure Configuration</h3>
                <p className="subtitle" style={{ margin: 0 }}>
                  Employee: {showStructureModal.fullName} ({showStructureModal.empCode})
                </p>
              </div>
              <button className="close-btn" onClick={() => setShowStructureModal(null)}>
                <X size={18} />
              </button>
            </div>
            <form onSubmit={handleSaveStructure}>
              <div className="modal-body-scroll">
                <div className="form-group" style={{ marginBottom: '1.25rem' }}>
                  <label htmlFor="effectiveFrom">Effective From Date</label>
                  <input
                    id="effectiveFrom"
                    type="date"
                    className="input"
                    value={effectiveFrom}
                    onChange={(e) => setEffectiveFrom(e.target.value)}
                    required
                  />
                </div>

                <div className="form-grid-3">
                  <div className="form-group">
                    <label htmlFor="basic">Basic Salary (Monthly)</label>
                    <input
                      id="basic"
                      type="number"
                      className="input"
                      value={basic}
                      onChange={(e) => setBasic(e.target.value)}
                      required
                      min={0}
                    />
                  </div>
                  <div className="form-group">
                    <label htmlFor="hra">HRA (House Rent Allowance)</label>
                    <input
                      id="hra"
                      type="number"
                      className="input"
                      value={hra}
                      onChange={(e) => setHra(e.target.value)}
                      min={0}
                    />
                  </div>
                  <div className="form-group">
                    <label htmlFor="da">DA (Dearness Allowance)</label>
                    <input
                      id="da"
                      type="number"
                      className="input"
                      value={da}
                      onChange={(e) => setDa(e.target.value)}
                      min={0}
                    />
                  </div>
                  <div className="form-group">
                    <label htmlFor="special">Special Allowance</label>
                    <input
                      id="special"
                      type="number"
                      className="input"
                      value={specialAllowance}
                      onChange={(e) => setSpecialAllowance(e.target.value)}
                      min={0}
                    />
                  </div>
                  <div className="form-group">
                    <label htmlFor="conveyance">Conveyance Allowance</label>
                    <input
                      id="conveyance"
                      type="number"
                      className="input"
                      value={conveyance}
                      onChange={(e) => setConveyance(e.target.value)}
                      min={0}
                    />
                  </div>
                  <div className="form-group">
                    <label htmlFor="medical">Medical Allowance</label>
                    <input
                      id="medical"
                      type="number"
                      className="input"
                      value={medical}
                      onChange={(e) => setMedical(e.target.value)}
                      min={0}
                    />
                  </div>
                  <div className="form-group">
                    <label htmlFor="lta">LTA (Leave Travel Allowance)</label>
                    <input
                      id="lta"
                      type="number"
                      className="input"
                      value={lta}
                      onChange={(e) => setLta(e.target.value)}
                      min={0}
                    />
                  </div>
                  <div className="form-group">
                    <label htmlFor="other">Other Allowances</label>
                    <input
                      id="other"
                      type="number"
                      className="input"
                      value={otherAllowances}
                      onChange={(e) => setOtherAllowances(e.target.value)}
                      min={0}
                    />
                  </div>
                </div>

                <div className="calculation-preview">
                  <h4>Real-time Calculation Estimates</h4>
                  <div className="calc-grid">
                    <div className="calc-row">
                      <span>Gross Monthly Salary</span>
                      <span className="calc-val">₹{calculatedGross.toLocaleString('en-IN')}</span>
                    </div>
                    <div className="calc-row">
                      <span>Employer PF Contribution (12% of Basic)</span>
                      <span className="calc-val">₹{calculatedPfEmployer.toLocaleString('en-IN')}</span>
                    </div>
                    <div className="calc-row">
                      <span>Employer ESI Contribution (3.25% if Gross ≤ 21k)</span>
                      <span className="calc-val">₹{calculatedEsiEmployer.toLocaleString('en-IN')}</span>
                    </div>
                    <div className="calc-row total-row">
                      <span>Total Estimated CTC (Monthly)</span>
                      <span className="calc-val highlight">₹{calculatedCtc.toLocaleString('en-IN')}</span>
                    </div>
                  </div>
                </div>
              </div>
              <div className="modal-footer">
                <button
                  type="button"
                  className="btn btn-secondary"
                  onClick={() => setShowStructureModal(null)}
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="btn btn-primary"
                  disabled={saveStructureMutation.isPending}
                >
                  {saveStructureMutation.isPending ? (
                    <>
                      <RefreshCw size={14} className="spinner" /> Saving...
                    </>
                  ) : (
                    'Save Salary Structure'
                  )}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* ─── MODAL: Payslip Detailed breakdown ─── */}
      {selectedPayslip && (
        <div className="modal-overlay">
          <div className="modal-container payslip-detail-modal glass">
            <div className="modal-header">
              <div>
                <h3>Payslip Details</h3>
                <p className="subtitle" style={{ margin: 0 }}>
                  Period: {getMonthName(selectedPayslip.periodMonth)} {selectedPayslip.periodYear}
                </p>
              </div>
              <button className="close-btn" onClick={() => setSelectedPayslip(null)}>
                <X size={18} />
              </button>
            </div>
            <div className="modal-body-scroll">
              <div className="payslip-branding">
                <div className="brand-logo">N</div>
                <div>
                  <div className="brand-name">NexusHR Enterprise</div>
                  <div className="brand-tag">Salary Statement & Compliance Record</div>
                </div>
              </div>

              <div className="info-block">
                <div className="info-grid">
                  <div>
                    <div className="info-lbl">Employee Name</div>
                    <div className="info-val">{selectedPayslip.employeeName}</div>
                  </div>
                  <div>
                    <div className="info-lbl">Employee Code</div>
                    <div className="info-val">{selectedPayslip.empCode}</div>
                  </div>
                  <div>
                    <div className="info-lbl">Department</div>
                    <div className="info-val">{selectedPayslip.department || 'N/A'}</div>
                  </div>
                  <div>
                    <div className="info-lbl">Designation</div>
                    <div className="info-val">{selectedPayslip.designation}</div>
                  </div>
                  <div>
                    <div className="info-lbl">Working Days</div>
                    <div className="info-val">{selectedPayslip.presentDays} / {selectedPayslip.workingDays}</div>
                  </div>
                  <div>
                    <div className="info-lbl">Loss of Pay Days</div>
                    <div className="info-val">{selectedPayslip.lossOfPayDays} days</div>
                  </div>
                </div>
              </div>

              <div className="breakdown-grid">
                <div>
                  <h4>Earnings</h4>
                  <table className="breakdown-table">
                    <tbody>
                      <tr>
                        <td>Basic Salary</td>
                        <td>₹{selectedPayslip.basic.toLocaleString('en-IN')}</td>
                      </tr>
                      <tr>
                        <td>HRA (House Rent)</td>
                        <td>₹{selectedPayslip.hra.toLocaleString('en-IN')}</td>
                      </tr>
                      <tr>
                        <td>DA (Dearness)</td>
                        <td>₹{selectedPayslip.da.toLocaleString('en-IN')}</td>
                      </tr>
                      <tr>
                        <td>Special Allowance</td>
                        <td>₹{selectedPayslip.specialAllowance.toLocaleString('en-IN')}</td>
                      </tr>
                      <tr>
                        <td>Other Allowances & Earnings</td>
                        <td>₹{selectedPayslip.otherEarnings.toLocaleString('en-IN')}</td>
                      </tr>
                      <tr className="gross-row">
                        <td>Gross Earnings</td>
                        <td>₹{selectedPayslip.gross.toLocaleString('en-IN')}</td>
                      </tr>
                    </tbody>
                  </table>
                </div>

                <div>
                  <h4>Deductions</h4>
                  <table className="breakdown-table">
                    <tbody>
                      <tr>
                        <td>Provident Fund (PF)</td>
                        <td>₹{selectedPayslip.pfEmployee.toLocaleString('en-IN')}</td>
                      </tr>
                      <tr>
                        <td>ESI Contribution</td>
                        <td>₹{selectedPayslip.esiEmployee.toLocaleString('en-IN')}</td>
                      </tr>
                      <tr>
                        <td>Professional Tax (PT)</td>
                        <td>₹{selectedPayslip.professionalTax.toLocaleString('en-IN')}</td>
                      </tr>
                      <tr>
                        <td>Income Tax (TDS)</td>
                        <td>₹{selectedPayslip.tds.toLocaleString('en-IN')}</td>
                      </tr>
                      <tr>
                        <td>Other Deductions</td>
                        <td>₹{selectedPayslip.otherDeductions.toLocaleString('en-IN')}</td>
                      </tr>
                      <tr className="gross-row">
                        <td>Total Deductions</td>
                        <td>₹{selectedPayslip.totalDeductions.toLocaleString('en-IN')}</td>
                      </tr>
                    </tbody>
                  </table>
                </div>
              </div>

              <div className="net-disbursed">
                <div className="disbursed-lbl">Net Salary Disbursed</div>
                <div className="disbursed-val">₹{selectedPayslip.netSalary.toLocaleString('en-IN')}</div>
              </div>
            </div>
            <div className="modal-footer">
              <button className="btn btn-secondary" onClick={() => setSelectedPayslip(null)}>
                Close
              </button>
              <button
                className="btn btn-primary"
                onClick={() => handleDownloadPdf(selectedPayslip.id, selectedPayslip.periodMonth, selectedPayslip.periodYear)}
              >
                <Download size={16} /> Download PDF Statement
              </button>
            </div>
          </div>
        </div>
      )}

      {/* ─── MODAL: View Run Payslips ─── */}
      {viewRunPayslips && (
        <div className="modal-overlay">
          <div className="modal-container run-payslips-modal glass">
            <div className="modal-header">
              <div>
                <h3>Payslips generated for Payroll Cycle</h3>
                <p className="subtitle" style={{ margin: 0 }}>
                  Period: {getMonthName(viewRunPayslips.periodMonth)} {viewRunPayslips.periodYear} ({viewRunPayslips.status})
                </p>
              </div>
              <button className="close-btn" onClick={() => setViewRunPayslips(null)}>
                <X size={18} />
              </button>
            </div>
            <div className="modal-body">
              {isLoadingRunPayslips ? (
                <div className="loading-state">
                  <RefreshCw className="spinner" size={32} />
                  <p>Loading payslips in this cycle...</p>
                </div>
              ) : !runPayslipsList || runPayslipsList.length === 0 ? (
                <div className="empty-state">
                  <AlertCircle size={48} />
                  <p>No payslips found in this cycle. Complete the processing cycle first.</p>
                </div>
              ) : (
                <div className="table-wrapper" style={{ maxHeight: '400px', overflowY: 'auto' }}>
                  <table className="table">
                    <thead>
                      <tr>
                        <th>Employee</th>
                        <th>Gross</th>
                        <th>Deductions</th>
                        <th>Net Salary</th>
                        <th>LOP</th>
                        <th style={{ textAlign: 'right' }}>Actions</th>
                      </tr>
                    </thead>
                    <tbody>
                      {runPayslipsList.map((p) => (
                        <tr key={p.id}>
                          <td>
                            <div className="emp-name" style={{ fontWeight: 600 }}>{p.employeeName}</div>
                            <div className="emp-code">{p.empCode}</div>
                          </td>
                          <td>₹{p.gross.toLocaleString('en-IN')}</td>
                          <td>₹{p.totalDeductions.toLocaleString('en-IN')}</td>
                          <td style={{ color: 'var(--color-text)', fontWeight: 600 }}>
                            ₹{p.netSalary.toLocaleString('en-IN')}
                          </td>
                          <td style={{ color: p.lossOfPayDays > 0 ? 'var(--color-danger)' : 'inherit' }}>
                            {p.lossOfPayDays} LOP
                          </td>
                          <td style={{ textAlign: 'right' }}>
                            <div className="action-row">
                              <button
                                className="btn btn-ghost btn-sm"
                                onClick={() => setSelectedPayslip(p)}
                                title="View Details"
                              >
                                <Eye size={14} /> View
                              </button>
                              <button
                                className="btn btn-secondary btn-sm"
                                onClick={() => handleDownloadPdf(p.id, p.periodMonth, p.periodYear)}
                                title="Download PDF"
                              >
                                <Download size={14} />
                              </button>
                            </div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
            <div className="modal-footer">
              <button className="btn btn-secondary" onClick={() => setViewRunPayslips(null)}>
                Close
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useAuth } from '../lib/auth';
import api from '../lib/api';
import type { Goal, PerformanceReview, ReviewCycle, PeerFeedback, NormalizationPreview, ApiResponse } from '../lib/types';
import {
  Target, Award, Users, ShieldAlert, Plus, Check, Edit2,
  TrendingUp, Award as AwardIcon, Star, CheckCircle
} from 'lucide-react';
import toast from 'react-hot-toast';
import './PerformancePage.css';

export default function PerformancePage() {
  const { user, hasRole } = useAuth();
  const queryClient = useQueryClient();
  const [activeTab, setActiveTab] = useState<'goals' | 'reviews' | 'feedback' | 'normalization'>('goals');
  const [selectedCycleId, setSelectedCycleId] = useState<number | null>(null);

  // Goal Form State
  const [showGoalModal, setShowGoalModal] = useState(false);
  const [editingGoal, setEditingGoal] = useState<Goal | null>(null);
  const [goalTitle, setGoalTitle] = useState('');
  const [goalDesc, setGoalDesc] = useState('');
  const [goalType, setGoalType] = useState<'COMPANY' | 'DEPARTMENT' | 'INDIVIDUAL'>('INDIVIDUAL');
  const [goalCategory, setGoalCategory] = useState('');
  const [targetVal, setTargetVal] = useState(100);
  const [currentVal, setCurrentVal] = useState(0);
  const [weight, setWeight] = useState(10);
  const [unit, setUnit] = useState('%');
  const [startDate, setStartDate] = useState('');
  const [dueDate, setDueDate] = useState('');

  // Review Form State
  const [showReviewModal, setShowReviewModal] = useState(false);
  const [selectedReview, setSelectedReview] = useState<PerformanceReview | null>(null);
  const [reviewGoalScore, setReviewGoalScore] = useState(3.0);
  const [reviewCompScore, setReviewCompScore] = useState(3.0);
  const [reviewStrengths, setReviewStrengths] = useState('');
  const [reviewImprovement, setReviewImprovement] = useState('');
  const [reviewComments, setReviewComments] = useState('');

  // Feedback Form State
  const [showFeedbackModal, setShowFeedbackModal] = useState(false);
  const [feedbackToEmpId, setFeedbackToEmpId] = useState('');
  const [feedbackRating, setFeedbackRating] = useState(4.0);
  const [feedbackStrengths, setFeedbackStrengths] = useState('');
  const [feedbackImprovement, setFeedbackImprovement] = useState('');
  const [feedbackComments, setFeedbackComments] = useState('');
  const [feedbackAnonymous, setFeedbackAnonymous] = useState(false);

  // Fetch cycles
  const { data: cycles } = useQuery<ReviewCycle[]>({
    queryKey: ['reviewCycles'],
    queryFn: () => api.get<ApiResponse<ReviewCycle[]>>('/performance/cycles').then(r => r.data.data),
  });

  const activeCycle = cycles?.find(c => c.status === 'ACTIVE') || cycles?.[0];
  const currentCycleId = selectedCycleId || activeCycle?.id;

  // Fetch logged in user's employee ID
  const empId = user?.employeeId || user?.id;

  // Fetch goals
  const { data: goals, isLoading: isLoadingGoals } = useQuery<Goal[]>({
    queryKey: ['employeeGoals', empId, currentCycleId],
    queryFn: () => {
      const url = currentCycleId 
        ? `/goals/employee/${empId}?cycleId=${currentCycleId}` 
        : `/goals/employee/${empId}`;
      return api.get<ApiResponse<Goal[]>>(url).then(r => r.data.data);
    },
    enabled: !!empId,
  });

  // Fetch logged in user's reviews
  const { data: myReviews, isLoading: isLoadingReviews } = useQuery<PerformanceReview[]>({
    queryKey: ['myReviews'],
    queryFn: () => api.get<ApiResponse<PerformanceReview[]>>('/performance/reviews/me').then(r => r.data.data),
  });

  // Fetch feedback for me
  const { data: feedbackForMe } = useQuery<PeerFeedback[]>({
    queryKey: ['feedbackForMe', currentCycleId, empId],
    queryFn: () => api.get<ApiResponse<PeerFeedback[]>>(`/performance/feedbacks/for/${empId}?cycleId=${currentCycleId}`).then(r => r.data.data),
    enabled: !!currentCycleId && !!empId,
  });

  // Normalization Preview
  const { data: normalizationData, refetch: refetchNormalization, isLoading: isLoadingNormalization } = useQuery<NormalizationPreview[]>({
    queryKey: ['normalization', currentCycleId],
    queryFn: () => api.get<ApiResponse<NormalizationPreview[]>>(`/performance/cycles/${currentCycleId}/normalize`).then(r => r.data.data),
    enabled: !!currentCycleId && (hasRole('ROLE_ADMIN') || hasRole('ROLE_HR_MANAGER')),
  });

  // Goal Mutations
  const saveGoalMutation = useMutation({
    mutationFn: (goalData: any) => {
      if (editingGoal) {
        return api.put<ApiResponse<Goal>>(`/goals/${editingGoal.id}`, goalData);
      }
      return api.post<ApiResponse<Goal>>('/goals', goalData);
    },
    onSuccess: () => {
      toast.success(editingGoal ? 'Goal updated successfully!' : 'Goal created successfully!');
      setShowGoalModal(false);
      setEditingGoal(null);
      resetGoalForm();
      queryClient.invalidateQueries({ queryKey: ['employeeGoals'] });
    },
    onError: (err: any) => {
      toast.error(err.response?.data?.message || 'Failed to save goal');
    }
  });

  const updateGoalProgressMutation = useMutation({
    mutationFn: ({ goalId, progress }: { goalId: number, progress: number }) => {
      // Fetch target goal to update currentValue proportionally
      const targetGoal = goals?.find(g => g.id === goalId);
      const targetValue = targetGoal?.targetValue || 100;
      const computedValue = (progress / 100) * Number(targetValue);
      return api.put<ApiResponse<Goal>>(`/goals/${goalId}`, {
        ...targetGoal,
        currentValue: computedValue
      });
    },
    onSuccess: () => {
      toast.success('Progress updated successfully!');
      queryClient.invalidateQueries({ queryKey: ['employeeGoals'] });
    },
    onError: () => toast.error('Failed to update progress')
  });

  // Submit Review Mutation
  const submitReviewMutation = useMutation({
    mutationFn: (reviewData: any) => api.post<ApiResponse<PerformanceReview>>('/performance/reviews', reviewData),
    onSuccess: () => {
      toast.success('Performance review submitted successfully!');
      setShowReviewModal(false);
      setSelectedReview(null);
      queryClient.invalidateQueries({ queryKey: ['myReviews'] });
    },
    onError: (err: any) => {
      toast.error(err.response?.data?.message || 'Failed to submit review');
    }
  });

  // Submit Feedback Mutation
  const submitFeedbackMutation = useMutation({
    mutationFn: (feedbackData: any) => api.post<ApiResponse<PeerFeedback>>('/performance/feedbacks', feedbackData),
    onSuccess: () => {
      toast.success('Peer feedback submitted successfully!');
      setShowFeedbackModal(false);
      resetFeedbackForm();
    },
    onError: (err: any) => {
      toast.error(err.response?.data?.message || 'Failed to submit peer feedback');
    }
  });

  // Apply Normalization Mutation
  const applyNormalizationMutation = useMutation({
    mutationFn: () => api.post<ApiResponse<NormalizationPreview[]>>(`/performance/cycles/${currentCycleId}/normalize`),
    onSuccess: () => {
      toast.success('Bell-curve normalization applied successfully!');
      queryClient.invalidateQueries({ queryKey: ['normalization'] });
      refetchNormalization();
    },
    onError: (err: any) => {
      toast.error(err.response?.data?.message || 'Failed to apply normalization');
    }
  });

  const resetGoalForm = () => {
    setGoalTitle('');
    setGoalDesc('');
    setGoalType('INDIVIDUAL');
    setGoalCategory('');
    setTargetVal(100);
    setCurrentVal(0);
    setWeight(10);
    setUnit('%');
    setStartDate('');
    setDueDate('');
  };

  const resetFeedbackForm = () => {
    setFeedbackToEmpId('');
    setFeedbackRating(4.0);
    setFeedbackStrengths('');
    setFeedbackImprovement('');
    setFeedbackComments('');
    setFeedbackAnonymous(false);
  };

  const handleEditGoal = (goal: Goal) => {
    setEditingGoal(goal);
    setGoalTitle(goal.title);
    setGoalDesc(goal.description);
    setGoalType(goal.type);
    setGoalCategory(goal.category);
    setTargetVal(Number(goal.targetValue));
    setCurrentVal(Number(goal.currentValue));
    setWeight(Number(goal.weight));
    setUnit(goal.unit);
    setStartDate(goal.startDate);
    setDueDate(goal.dueDate);
    setShowGoalModal(true);
  };

  const handleSaveGoal = (e: React.FormEvent) => {
    e.preventDefault();
    if (!goalTitle || !startDate || !dueDate || !currentCycleId) {
      toast.error('Please fill in all required fields.');
      return;
    }
    saveGoalMutation.mutate({
      employeeId: empId,
      reviewCycleId: currentCycleId,
      title: goalTitle,
      description: goalDesc,
      type: goalType,
      category: goalCategory || 'General',
      targetValue: targetVal,
      currentValue: currentVal,
      weight: weight,
      unit: unit,
      startDate: startDate,
      dueDate: dueDate,
      status: editingGoal ? editingGoal.status : 'PENDING'
    });
  };

  const handleOpenReviewModal = (review: PerformanceReview) => {
    setSelectedReview(review);
    setReviewGoalScore(Number(review.goalScore) || 3.0);
    setReviewCompScore(Number(review.competencyScore) || 3.0);
    setReviewStrengths(review.strengths || '');
    setReviewImprovement(review.improvementAreas || '');
    setReviewComments(review.reviewType === 'SELF' ? review.employeeComments || '' : review.managerComments || '');
    setShowReviewModal(true);
  };

  const handleSaveReview = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedReview) return;

    submitReviewMutation.mutate({
      employeeId: selectedReview.employeeId,
      reviewerId: empId,
      cycleId: selectedReview.cycleId,
      reviewType: selectedReview.reviewType,
      goalScore: reviewGoalScore,
      competencyScore: reviewCompScore,
      strengths: reviewStrengths,
      improvementAreas: reviewImprovement,
      comments: reviewComments
    });
  };

  const handleSaveFeedback = (e: React.FormEvent) => {
    e.preventDefault();
    if (!feedbackToEmpId || !currentCycleId) {
      toast.error('Please select an employee.');
      return;
    }
    submitFeedbackMutation.mutate({
      reviewCycleId: currentCycleId,
      fromEmployeeId: empId,
      toEmployeeId: Number(feedbackToEmpId),
      rating: feedbackRating,
      strengths: feedbackStrengths,
      improvementAreas: feedbackImprovement,
      comments: feedbackComments,
      anonymous: feedbackAnonymous
    });
  };

  return (
    <div className="page-content">
      <div className="page-header">
        <div>
          <h1>Performance Management</h1>
          <p>OKR Goals, 360 Evaluations, and Rating Distributions</p>
        </div>
        <div className="header-actions">
          {cycles && cycles.length > 0 && (
            <select
              className="select cycle-selector"
              value={currentCycleId || ''}
              onChange={(e) => setSelectedCycleId(Number(e.target.value))}
            >
              {cycles.map((c) => (
                <option key={c.id} value={c.id}>
                  {c.name} ({c.status})
                </option>
              ))}
            </select>
          )}
          {activeTab === 'goals' && (
            <button className="btn btn-primary" onClick={() => { setEditingGoal(null); resetGoalForm(); setShowGoalModal(true); }}>
              <Plus size={16} /> Add OKR Goal
            </button>
          )}
          {activeTab === 'feedback' && (
            <button className="btn btn-primary" onClick={() => setShowFeedbackModal(true)}>
              <Star size={16} /> Submit Peer Feedback
            </button>
          )}
        </div>
      </div>

      {/* Tabs */}
      <div className="tabs">
        <button className={`tab ${activeTab === 'goals' ? 'active' : ''}`} onClick={() => setActiveTab('goals')}>
          <Target size={16} /> Goals & OKRs
        </button>
        <button className={`tab ${activeTab === 'reviews' ? 'active' : ''}`} onClick={() => setActiveTab('reviews')}>
          <Award size={16} /> Performance Reviews
        </button>
        <button className={`tab ${activeTab === 'feedback' ? 'active' : ''}`} onClick={() => setActiveTab('feedback')}>
          <Users size={16} /> Peer Feedback
        </button>
        {(hasRole('ROLE_ADMIN') || hasRole('ROLE_HR_MANAGER')) && (
          <button className={`tab ${activeTab === 'normalization' ? 'active' : ''}`} onClick={() => setActiveTab('normalization')}>
            <TrendingUp size={16} /> Rating Normalization
          </button>
        )}
      </div>

      {/* Goal Content */}
      {activeTab === 'goals' && (
        <div className="performance-section animate-fade">
          {isLoadingGoals ? (
            <div className="empty-state"><div className="spinner" /></div>
          ) : !goals || goals.length === 0 ? (
            <div className="card empty-state">
              <Target size={48} />
              <h3>No goals set for this cycle</h3>
              <p>Goals help define OKRs and SMART tracking. Create your first goal to get started.</p>
              <button className="btn btn-primary" onClick={() => setShowGoalModal(true)}>
                <Plus size={16} /> Create Goal
              </button>
            </div>
          ) : (
            <div className="grid grid-cols-2">
              {goals.map((goal) => {
                const calculatedProgress = goal.progress ?? Math.min(100, Math.round((Number(goal.currentValue) / Number(goal.targetValue)) * 100));
                return (
                  <div key={goal.id} className="card goal-card">
                    <div className="goal-card-header">
                      <span className={`badge badge-goal-type ${goal.type.toLowerCase()}`}>{goal.type}</span>
                      <span className={`badge badge-goal-status ${goal.status.toLowerCase().replace('_', '-')}`}>
                        {goal.status.replace('_', ' ')}
                      </span>
                    </div>
                    <h3 className="goal-title">{goal.title}</h3>
                    <p className="goal-desc">{goal.description}</p>

                    <div className="goal-metrics">
                      <div className="metric">
                        <span className="label">Target:</span>
                        <span className="value">{Number(goal.targetValue)} {goal.unit}</span>
                      </div>
                      <div className="metric">
                        <span className="label">Current:</span>
                        <span className="value">{Number(goal.currentValue)} {goal.unit}</span>
                      </div>
                      <div className="metric">
                        <span className="label">Weight:</span>
                        <span className="value">{Number(goal.weight)}%</span>
                      </div>
                    </div>

                    <div className="goal-progress-section">
                      <div className="progress-text">
                        <span>Progress</span>
                        <span>{calculatedProgress}%</span>
                      </div>
                      <div className="progress-bar-container">
                        <div className="progress-bar" style={{ width: `${calculatedProgress}%` }} />
                      </div>
                      <input
                        type="range"
                        min="0"
                        max="100"
                        value={calculatedProgress}
                        onChange={(e) => updateGoalProgressMutation.mutate({ goalId: goal.id, progress: Number(e.target.value) })}
                        className="progress-slider"
                      />
                    </div>

                    <div className="goal-card-actions">
                      <button className="btn-ghost btn-sm" onClick={() => handleEditGoal(goal)}>
                        <Edit2 size={14} /> Edit details
                      </button>
                      <div className="goal-dates">
                        Due: {new Date(goal.dueDate).toLocaleDateString()}
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      )}

      {/* Reviews Content */}
      {activeTab === 'reviews' && (
        <div className="performance-section animate-fade">
          {isLoadingReviews ? (
            <div className="empty-state"><div className="spinner" /></div>
          ) : !myReviews || myReviews.length === 0 ? (
            <div className="card empty-state">
              <AwardIcon size={48} />
              <h3>No reviews cycles assigned</h3>
              <p>You will see self and manager evaluations here once the cycle moves to evaluation state.</p>
            </div>
          ) : (
            <div className="reviews-list">
              {myReviews.map((rev) => (
                <div key={rev.id} className="card review-item-card">
                  <div className="review-meta">
                    <div>
                      <span className="badge badge-review-type">{rev.reviewType} Review</span>
                      <span className={`badge badge-review-status ${rev.status.toLowerCase()}`}>{rev.status}</span>
                    </div>
                    <span className="review-cycle-title">{rev.cycleName}</span>
                  </div>

                  <div className="review-details-grid">
                    <div className="detail-col">
                      <div className="detail-label">Employee</div>
                      <div className="detail-val">{rev.employeeName}</div>
                    </div>
                    <div className="detail-col">
                      <div className="detail-label">Reviewer</div>
                      <div className="detail-val">{rev.reviewerName || 'Unassigned'}</div>
                    </div>
                    <div className="detail-col">
                      <div className="detail-label">Final Score</div>
                      <div className="detail-val highlight">{rev.finalScore ? Number(rev.finalScore).toFixed(1) : 'Pending'}</div>
                    </div>
                    <div className="detail-col">
                      <div className="detail-label">Rating Band</div>
                      <div className="detail-val highlight">{rev.band || 'Pending'}</div>
                    </div>
                  </div>

                  <div className="review-actions">
                    <button className="btn btn-secondary" onClick={() => handleOpenReviewModal(rev)}>
                      {rev.status === 'DRAFT' ? 'Fill Evaluation' : 'View Details'}
                    </button>
                    {rev.status === 'SUBMITTED' && rev.reviewerId !== empId && (
                      <button
                        className="btn btn-primary"
                        onClick={async () => {
                          await api.post(`/performance/reviews/${rev.id}/acknowledge`);
                          toast.success('Review acknowledged!');
                          queryClient.invalidateQueries({ queryKey: ['myReviews'] });
                        }}
                      >
                        <CheckCircle size={14} /> Acknowledge Review
                      </button>
                    )}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {/* Feedback Content */}
      {activeTab === 'feedback' && (
        <div className="performance-section animate-fade">
          <div className="feedback-layout">
            <div className="card feedback-received-card">
              <h3><Users size={18} /> Peer Feedbacks Received</h3>
              {!feedbackForMe || feedbackForMe.length === 0 ? (
                <div className="empty-state">
                  <Star size={36} />
                  <p>No feedback received yet in this cycle</p>
                </div>
              ) : (
                <div className="feedback-list">
                  {feedbackForMe.map((fb) => (
                    <div key={fb.id} className="feedback-card-item">
                      <div className="fb-header">
                        <span className="fb-from">{fb.anonymous ? 'Anonymous Colleague' : fb.fromEmployeeName}</span>
                        <div className="fb-rating">
                          <Star size={12} className="star-filled" /> {Number(fb.rating).toFixed(1)}
                        </div>
                      </div>
                      <div className="fb-text">
                        <strong>Strengths:</strong> {fb.strengths}
                      </div>
                      <div className="fb-text">
                        <strong>Improvement Areas:</strong> {fb.improvementAreas}
                      </div>
                      {fb.comments && (
                        <div className="fb-comments">
                          "{fb.comments}"
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              )}
            </div>

            <div className="card feedback-guidelines">
              <h3>360 Feedback Guidelines</h3>
              <p>Giving constructive feedback helps coworkers grow. Focus on:</p>
              <ul>
                <li><strong>Actionable insights:</strong> Suggest specific ways to improve.</li>
                <li><strong>Objectivity:</strong> Avoid personal bias and focus on work outcomes.</li>
                <li><strong>Encouragement:</strong> Recognize strengths and milestones.</li>
              </ul>
              <button className="btn btn-primary" style={{ marginTop: '1rem', width: '100%' }} onClick={() => setShowFeedbackModal(true)}>
                Submit New Feedback
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Normalization Content */}
      {activeTab === 'normalization' && (
        <div className="performance-section animate-fade">
          <div className="card normalization-dashboard">
            <div className="normalization-header">
              <div>
                <h3>Bell-Curve Rating Normalization</h3>
                <p>Ensuring balanced employee rating distributions across the company.</p>
              </div>
              <button
                className="btn btn-primary"
                onClick={() => applyNormalizationMutation.mutate()}
                disabled={applyNormalizationMutation.isPending || !normalizationData || normalizationData.length === 0}
              >
                <Check size={16} /> Apply Bell-Curve Normalization
              </button>
            </div>

            {isLoadingNormalization ? (
              <div className="empty-state"><div className="spinner" /></div>
            ) : !normalizationData || normalizationData.length === 0 ? (
              <div className="empty-state">
                <ShieldAlert size={36} />
                <p>No active evaluations to normalize in this cycle.</p>
              </div>
            ) : (
              <div className="table-wrapper">
                <table className="table">
                  <thead>
                    <tr>
                      <th>Employee</th>
                      <th>Department</th>
                      <th>Raw Score</th>
                      <th>Current Band</th>
                      <th>Suggested normalized Band</th>
                      <th>Status</th>
                    </tr>
                  </thead>
                  <tbody>
                    {normalizationData.map((row) => (
                      <tr key={row.reviewId}>
                        <td>{row.employeeName}</td>
                        <td>{row.departmentName}</td>
                        <td>{Number(row.finalScore).toFixed(2)}</td>
                        <td><span className="badge badge-normal-current">{row.currentBand || 'N/A'}</span></td>
                        <td><span className="badge badge-normal-suggested">{row.suggestedBand}</span></td>
                        <td>
                          {row.currentBand === row.suggestedBand ? (
                            <span className="status-no-change">Matched</span>
                          ) : (
                            <span className="status-adjusted">Adjusted</span>
                          )}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Add/Edit Goal Modal */}
      {showGoalModal && (
        <div className="modal-overlay">
          <div className="modal-content card">
            <h2>{editingGoal ? 'Edit Goal' : 'Create SMART Goal'}</h2>
            <form onSubmit={handleSaveGoal}>
              <div className="grid grid-cols-2">
                <div>
                  <label className="form-label">Goal Title *</label>
                  <input type="text" className="input" value={goalTitle} onChange={(e) => setGoalTitle(e.target.value)} required />
                </div>
                <div>
                  <label className="form-label">Type</label>
                  <select className="select" value={goalType} onChange={(e: any) => setGoalType(e.target.value)}>
                    <option value="INDIVIDUAL">Individual</option>
                    <option value="DEPARTMENT">Department</option>
                    <option value="COMPANY">Company</option>
                  </select>
                </div>
                <div>
                  <label className="form-label">Category</label>
                  <input type="text" className="input" placeholder="e.g. Sales, Coding" value={goalCategory} onChange={(e) => setGoalCategory(e.target.value)} />
                </div>
                <div>
                  <label className="form-label">Weight (%)</label>
                  <input type="number" className="input" value={weight} onChange={(e) => setWeight(Number(e.target.value))} min="1" max="100" />
                </div>
                <div>
                  <label className="form-label">Target Value</label>
                  <input type="number" className="input" value={targetVal} onChange={(e) => setTargetVal(Number(e.target.value))} />
                </div>
                <div>
                  <label className="form-label">Unit</label>
                  <input type="text" className="input" value={unit} onChange={(e) => setUnit(e.target.value)} />
                </div>
                <div>
                  <label className="form-label">Start Date *</label>
                  <input type="date" className="input" value={startDate} onChange={(e) => setStartDate(e.target.value)} required />
                </div>
                <div>
                  <label className="form-label">Due Date *</label>
                  <input type="date" className="input" value={dueDate} onChange={(e) => setDueDate(e.target.value)} required />
                </div>
              </div>
              <div style={{ marginTop: '1rem' }}>
                <label className="form-label">Goal Description</label>
                <textarea className="textarea" value={goalDesc} onChange={(e) => setGoalDesc(e.target.value)} />
              </div>
              <div className="modal-actions">
                <button type="button" className="btn btn-secondary" onClick={() => setShowGoalModal(false)}>Cancel</button>
                <button type="submit" className="btn btn-primary" disabled={saveGoalMutation.isPending}>Save Goal</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Review Dialog Modal */}
      {showReviewModal && selectedReview && (
        <div className="modal-overlay">
          <div className="modal-content card">
            <h2>{selectedReview.reviewType} Performance Review</h2>
            <p className="subtitle">{selectedReview.employeeName} · {selectedReview.employeeDesignation}</p>

            <form onSubmit={handleSaveReview}>
              <div className="grid grid-cols-2" style={{ marginTop: '1rem' }}>
                <div>
                  <label className="form-label">Goal Achievement Score (1.0 - 5.0)</label>
                  <input
                    type="number"
                    step="0.1"
                    min="1"
                    max="5"
                    className="input"
                    value={reviewGoalScore}
                    onChange={(e) => setReviewGoalScore(Number(e.target.value))}
                    disabled={selectedReview.status !== 'DRAFT'}
                  />
                </div>
                <div>
                  <label className="form-label">Core Competency Score (1.0 - 5.0)</label>
                  <input
                    type="number"
                    step="0.1"
                    min="1"
                    max="5"
                    className="input"
                    value={reviewCompScore}
                    onChange={(e) => setReviewCompScore(Number(e.target.value))}
                    disabled={selectedReview.status !== 'DRAFT'}
                  />
                </div>
              </div>

              <div style={{ marginTop: '1rem' }}>
                <label className="form-label">Strengths</label>
                <textarea
                  className="textarea"
                  value={reviewStrengths}
                  onChange={(e) => setReviewStrengths(e.target.value)}
                  placeholder="Identify areas of excellence..."
                  disabled={selectedReview.status !== 'DRAFT'}
                />
              </div>

              <div style={{ marginTop: '1rem' }}>
                <label className="form-label">Areas for Improvement</label>
                <textarea
                  className="textarea"
                  value={reviewImprovement}
                  onChange={(e) => setReviewImprovement(e.target.value)}
                  placeholder="Key development suggestions..."
                  disabled={selectedReview.status !== 'DRAFT'}
                />
              </div>

              <div style={{ marginTop: '1rem' }}>
                <label className="form-label">Comments</label>
                <textarea
                  className="textarea"
                  value={reviewComments}
                  onChange={(e) => setReviewComments(e.target.value)}
                  placeholder="Additional remarks..."
                  disabled={selectedReview.status !== 'DRAFT'}
                />
              </div>

              <div className="modal-actions" style={{ marginTop: '1.5rem' }}>
                <button type="button" className="btn btn-secondary" onClick={() => setShowReviewModal(false)}>Close</button>
                {selectedReview.status === 'DRAFT' && (
                  <button type="submit" className="btn btn-primary" disabled={submitReviewMutation.isPending}>Submit Evaluation</button>
                )}
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Peer Feedback Submission Modal */}
      {showFeedbackModal && (
        <div className="modal-overlay">
          <div className="modal-content card">
            <h2>Submit Peer Feedback</h2>
            <p className="subtitle">Provide feedback for a colleague's professional growth.</p>
            <form onSubmit={handleSaveFeedback}>
              <div style={{ marginTop: '1rem' }}>
                <label className="form-label">Select Employee *</label>
                <input
                  type="number"
                  className="input"
                  placeholder="Enter employee ID..."
                  value={feedbackToEmpId}
                  onChange={(e) => setFeedbackToEmpId(e.target.value)}
                  required
                />
              </div>

              <div style={{ marginTop: '1.5rem' }}>
                <label className="form-label">Rating (1.0 - 5.0)</label>
                <input
                  type="number"
                  step="0.1"
                  min="1"
                  max="5"
                  className="input"
                  value={feedbackRating}
                  onChange={(e) => setFeedbackRating(Number(e.target.value))}
                />
              </div>

              <div style={{ marginTop: '1rem' }}>
                <label className="form-label">Strengths</label>
                <textarea
                  className="textarea"
                  value={feedbackStrengths}
                  onChange={(e) => setFeedbackStrengths(e.target.value)}
                  placeholder="What did they do exceptionally well?"
                />
              </div>

              <div style={{ marginTop: '1rem' }}>
                <label className="form-label">Areas for Improvement</label>
                <textarea
                  className="textarea"
                  value={feedbackImprovement}
                  onChange={(e) => setFeedbackImprovement(e.target.value)}
                  placeholder="What skills should they focus on developing?"
                />
              </div>

              <div style={{ marginTop: '1rem' }}>
                <label className="form-label">Comments</label>
                <textarea
                  className="textarea"
                  value={feedbackComments}
                  onChange={(e) => setFeedbackComments(e.target.value)}
                  placeholder="General notes..."
                />
              </div>

              <div style={{ marginTop: '1rem', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                <input
                  type="checkbox"
                  id="anonymousCheck"
                  checked={feedbackAnonymous}
                  onChange={(e) => setFeedbackAnonymous(e.target.checked)}
                />
                <label htmlFor="anonymousCheck" style={{ fontSize: '0.85rem', color: 'var(--color-text-secondary)' }}>
                  Submit anonymously
                </label>
              </div>

              <div className="modal-actions" style={{ marginTop: '1.5rem' }}>
                <button type="button" className="btn btn-secondary" onClick={() => setShowFeedbackModal(false)}>Cancel</button>
                <button type="submit" className="btn btn-primary" disabled={submitFeedbackMutation.isPending}>Submit Feedback</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState } from 'react';
import { useAuth } from '../lib/auth';
import api from '../lib/api';
import { Shield, Key, User, CheckCircle2, AlertCircle } from 'lucide-react';
import toast from 'react-hot-toast';
import './SettingsPage.css';

export default function SettingsPage() {
  const { user } = useAuth();
  const [currentPassword, setCurrentPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (newPassword.length < 8) {
      setError('New password must be at least 8 characters long.');
      return;
    }

    if (newPassword !== confirmPassword) {
      setError('New passwords do not match.');
      return;
    }

    setLoading(true);
    try {
      await api.post('/auth/change-password', {
        currentPassword,
        newPassword,
      });
      toast.success('Password changed successfully!');
      setCurrentPassword('');
      setNewPassword('');
      setConfirmPassword('');
    } catch (err: any) {
      const msg = err.response?.data?.message || 'Failed to change password. Please try again.';
      setError(msg);
      toast.error(msg);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="page-content settings-page animate-fade-in">
      <div className="page-header">
        <div>
          <h1>Account Settings</h1>
          <p>Manage your account credentials and personal preferences</p>
        </div>
      </div>

      <div className="settings-grid">
        {/* Profile Card */}
        <div className="card settings-card profile-section">
          <div className="card-header">
            <h3>
              <User size={18} /> User Profile
            </h3>
          </div>
          <div className="profile-details">
            <div className="avatar-large">
              {user?.fullName
                ?.split(' ')
                .map((n) => n[0])
                .join('')
                .substring(0, 2) ?? 'U'}
            </div>
            <div className="profile-info">
              <h2>{user?.fullName}</h2>
              <p className="email">{user?.email}</p>
              <div className="roles-badges">
                {user?.roles?.map((role) => (
                  <span key={role} className="badge badge-role">
                    {role.replace('ROLE_', '')}
                  </span>
                ))}
              </div>
            </div>
          </div>

          <div className="details-list">
            <div className="details-item">
              <span className="label">Username</span>
              <span className="value">{user?.username}</span>
            </div>
            <div className="details-item">
              <span className="label">Employee ID</span>
              <span className="value">{user?.employeeId ? `NEX-${String(user.employeeId).padStart(4, '0')}` : 'N/A'}</span>
            </div>
            <div className="details-item">
              <span className="label">Status</span>
              <span className="value status-active">
                <CheckCircle2 size={14} /> Active Account
              </span>
            </div>
          </div>
        </div>

        {/* Change Password Card */}
        <div className="card settings-card password-section">
          <div className="card-header">
            <h3>
              <Shield size={18} /> Credentials & Security
            </h3>
          </div>

          <form onSubmit={handleSubmit} className="settings-form">
            {error && (
              <div className="alert alert-danger">
                <AlertCircle size={16} />
                <span>{error}</span>
              </div>
            )}

            <div className="form-group">
              <label className="form-label" htmlFor="currentPassword">
                Current Password
              </label>
              <div className="input-with-icon">
                <Key size={16} className="input-icon" />
                <input
                  id="currentPassword"
                  type="password"
                  className="input"
                  placeholder="••••••••"
                  value={currentPassword}
                  onChange={(e) => setCurrentPassword(e.target.value)}
                  required
                />
              </div>
            </div>

            <div className="form-group">
              <label className="form-label" htmlFor="newPassword">
                New Password
              </label>
              <div className="input-with-icon">
                <Key size={16} className="input-icon" />
                <input
                  id="newPassword"
                  type="password"
                  className="input"
                  placeholder="•••••••• (Min 8 characters)"
                  value={newPassword}
                  onChange={(e) => setNewPassword(e.target.value)}
                  required
                />
              </div>
            </div>

            <div className="form-group">
              <label className="form-label" htmlFor="confirmPassword">
                Confirm New Password
              </label>
              <div className="input-with-icon">
                <Key size={16} className="input-icon" />
                <input
                  id="confirmPassword"
                  type="password"
                  className="input"
                  placeholder="••••••••"
                  value={confirmPassword}
                  onChange={(e) => setConfirmPassword(e.target.value)}
                  required
                />
              </div>
            </div>

            <button type="submit" className="btn btn-primary settings-btn" disabled={loading}>
              {loading ? <span className="spinner" style={{ width: 16, height: 16 }} /> : 'Update Password'}
            </button>
          </form>
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../lib/auth';
import { Eye, EyeOff, UserPlus } from 'lucide-react';
import './LoginPage.css';

export default function SignupPage() {
  const [fullName, setFullName] = useState('');
  const [email, setEmail] = useState('');
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const { signup, isAuthenticated } = useAuth();
  const navigate = useNavigate();

  useEffect(() => {
    if (isAuthenticated) {
      navigate('/', { replace: true });
    }
  }, [isAuthenticated, navigate]);

  if (isAuthenticated) {
    return null;
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (username.length < 3 || username.length > 50) {
      setError('Username must be between 3 and 50 characters.');
      return;
    }

    if (password.length < 8) {
      setError('Password must be at least 8 characters long.');
      return;
    }

    if (password !== confirmPassword) {
      setError('Passwords do not match.');
      return;
    }

    setLoading(true);
    try {
      await signup(username, email, fullName, password);
      navigate('/');
    } catch (err: any) {
      setError(err.response?.data?.message || 'Failed to create account. Please check your inputs.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="login-page">
      <div className="login-bg">
        <div className="bg-orb bg-orb-1" />
        <div className="bg-orb bg-orb-2" />
        <div className="bg-orb bg-orb-3" />
        <div className="bg-grid" />
      </div>

      <div className="login-card glass" style={{ maxWidth: '460px' }}>
        <div className="login-header">
          <div className="login-logo">
            <UserPlus size={28} />
          </div>
          <h1 className="login-title">Create Account</h1>
          <p className="login-subtitle">Join the NexusHR Workforce Intelligence Platform</p>
        </div>

        <form onSubmit={handleSubmit} className="login-form">
          {error && <div className="login-error">{error}</div>}

          <div className="form-group">
            <label className="form-label" htmlFor="fullName">
              Full Name
            </label>
            <input
              id="fullName"
              type="text"
              className="input"
              placeholder="John Doe"
              value={fullName}
              onChange={(e) => setFullName(e.target.value)}
              required
              autoFocus
            />
          </div>

          <div className="form-group">
            <label className="form-label" htmlFor="email">
              Email Address
            </label>
            <input
              id="email"
              type="email"
              className="input"
              placeholder="john.doe@example.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
            />
          </div>

          <div className="form-group">
            <label className="form-label" htmlFor="username">
              Username
            </label>
            <input
              id="username"
              type="text"
              className="input"
              placeholder="johndoe"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              required
            />
          </div>

          <div className="form-group">
            <label className="form-label" htmlFor="password">
              Password
            </label>
            <div className="password-wrapper">
              <input
                id="password"
                type={showPassword ? 'text' : 'password'}
                className="input"
                placeholder="••••••••"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required
              />
              <button
                type="button"
                className="password-toggle"
                onClick={() => setShowPassword(!showPassword)}
                tabIndex={-1}
              >
                {showPassword ? <EyeOff size={16} /> : <Eye size={16} />}
              </button>
            </div>
          </div>

          <div className="form-group">
            <label className="form-label" htmlFor="confirmPassword">
              Confirm Password
            </label>
            <input
              id="confirmPassword"
              type="password"
              className="input"
              placeholder="••••••••"
              value={confirmPassword}
              onChange={(e) => setConfirmPassword(e.target.value)}
              required
            />
          </div>

          <button
            type="submit"
            className="btn btn-primary login-btn"
            disabled={loading || !fullName || !email || !username || !password || !confirmPassword}
          >
            {loading ? <span className="spinner" style={{ width: 18, height: 18, borderWidth: 2 }} /> : 'Sign Up'}
          </button>

          <p className="login-hint">
            Already have an account?{' '}
            <span
              onClick={() => navigate('/login')}
              style={{ cursor: 'pointer', color: 'var(--color-primary-hover)', fontWeight: 'bold' }}
            >
              Sign In
            </span>
          </p>
        </form>
      </div>
    </div>
  );
}
